def is_majority(arr, n, x):
    """
    Check if x is a majority element in the sorted array arr of size n.
    A majority element appears more than n/2 times.
    """
    if n == 0:
        return False

    # Find the first occurrence of x using binary search
    def find_first(arr, n, x):
        low, high = 0, n - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                result = mid
                high = mid - 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return result

    first = find_first(arr, n, x)
    if first == -1:
        return False

    # Find the last occurrence of x using binary search
    def find_last(arr, n, x):
        low, high = 0, n - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                result = mid
                low = mid + 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return result

    last = find_last(arr, n, x)
    count = last - first + 1

    return count > n // 2
```

