def find_peak(arr, n):
    """
    Find the index of a peak element in the array.
    A peak element is one that is greater than its neighbors.
    """
    if n == 0:
        return -1
    if n == 1:
        return 0
    if arr[0] > arr[1]:
        return 0
    if arr[n - 1] > arr[n - 2]:
        return n - 1

    left, right = 1, n - 2
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] > arr[mid - 1] and arr[mid] > arr[mid + 1]:
            return mid
        elif arr[mid] < arr[mid - 1]:
            right = mid - 1
        else:
            left = mid + 1

    return -1
