def tuple_intersection(tuple_list1, tuple_list2):
    """
    Find the intersection of two lists of tuples, where tuples are considered
    equal irrespective of their order (i.e., (a, b) == (b, a)).
    Returns a set of tuples in canonical form (sorted elements).
    """
    def canonical(t):
        return tuple(sorted(t))

    set1 = {canonical(t) for t in tuple_list1}
    set2 = {canonical(t) for t in tuple_list2}

