    # DP: dp[mask][last] = number of ways to form a permutation using elements in mask, ending with element 'last'
    # mask is a bitmask of which elements have been used
    # last is the index of the last element in the permutation

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(mask, last):
        if mask == (1 << n) - 1:
            return 1
        count = 0
        for nxt in range(n):
            if not (mask & (1 << nxt)) and adj[last][nxt]:
                count = (count + dp(mask | (1 << nxt), nxt)) % MOD
        return count

    total = 0
    for i in range(n):
        total = (total + dp(1 << i, i)) % MOD

    print(total)

